    {
      "вещество": "Яблочная и лимонная кислоты (органические кислоты)",
      "содержание": "неизвестно (в пределах 0,1–0,5 % сухого веса)",
      "влияние": "Обеспечивают характерный кисловатый привкус; в пищевых концентрациях физиологически незначимы."
    }
  ]
}

